def group_by_first_char(words: list[str]) -> dict[str, list[str]]:
    grouped = {}
    for word in words:
        if not word:
            continue
        first_char = word[0]
        if first_char not in grouped:
            grouped[first_char] = []
        grouped[first_char].append(word)
    return grouped
